const attacks=(n)=>n>=12?3:n>=5?2:1;
const $=(id)=>document.getElementById('b05-'+id);
const options=Object.entries(weapons).map(([id,w])=>({id,label:w.group.startsWith('Versátil')?`${w.name} (${w.group.includes('duas mãos')?'2 mãos':'1 mão'})`:w.name}));
for (const id of ['weaponA','weaponB']){for(const o of options){const opt=document.createElement('option');opt.value=o.id;opt.textContent=o.label;$(id).append(opt)}}
